/// <summary>
///     AVA <c>avaICProjProdExist</c> method.
///     AVA - Schneider 19.08.2024
/// </summary>
/// <param name="_projId">
///     <c>ProjId</c> as type
/// </param>
/// <param name="_dataAreaId">
///     <c>DataAreaId</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean avaICProjExist(  ProjId      _projId, 
                                DataAreaId  _dataAreaId = this.dataAreaId   )
{
    boolean     retVal;

    DataAreaId  locDataAreaId;

    locDataAreaId = _dataAreaId;

    if(locDataAreaId == '')
    {
        locDataAreaId = curExt();
    }

    //if(this.AVAICProjProd)
    if(_projId)
    {
        if (locDataAreaId == curExt())
        {
            if(ProjTable::find(_projId).RecId)
            {
                retVal = true;
            }
        }
        else
        {
            changecompany(_dataAreaId)
            {
                if(ProjTable::find(_projId).RecId)
                {
                    retVal = true;
                }
            }
        }
    }
    return retVal;
}

/// <summary>
