/// <summary>
/// AVA/WEN/2025/05/15   AVA_013002_ResourceCalendar
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    KCS_PTMReleaseStatusTable   releaseStatusTable;

    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(KCS_PTMToolTable, ReleaseStatus):
            releaseStatusTable = KCS_PTMReleaseStatusTable::find(this.ReleaseStatus);
            if (releaseStatusTable.CalendarId && !this.avasetCalendar(releaseStatusTable))
            {
                this.ReleaseStatus = this.orig().ReleaseStatus;
            }
            break;
        case fieldNum(KCS_PTMToolTable, ReleaseStatusExt):
            ReleaseStatusTable = KCS_PTMReleaseStatusTable::find(this.ReleaseStatusExt);
            if (releaseStatusTable.CalendarId && !this.avasetCalendar(releaseStatusTable))
            {
                this.ReleaseStatusExt = this.orig().ReleaseStatusExt;
            }
            break;

    }
}

/// <summary>
/// AVA/WEN/2025/05/15   AVA_013002_ResourceCalendar
/// </summary>
/// <param name = "_releaseStatusTable">KCS_PTMReleaseStatusTable</param>
/// <returns>boolean</returns>
public boolean avaCheckCalendar(KCS_PTMReleaseStatusTable _releaseStatusTable)
{
    WrkCtrTable wrkCtrTable;
    boolean ret = true;

    if (_releaseStatusTable.CalendarId)
    {
        wrkCtrTable = wrkCtrTable::find(this.ToolId);
        if (!wrkCtrTable)
        {
            ret = checkFailed(strFmt("@NDX:NXAResourceNotFound", this.ToolId));
        }
    }
    return ret;
}

/// <summary>
/// AVA/WEN/2025/05/15   AVA_013002_ResourceCalendar
/// </summary>
/// <param name = "_releaseStatusTable">KCS_PTMReleaseStatusTable</param>
/// <returns>boolean</returns>
public boolean avaSetCalendar(KCS_PTMReleaseStatusTable _releaseStatusTable)
{
    boolean ret = false;
    Args args = new Args();
    MenuFunction    menuFunction;

    if (this.avaCheckCalendar(_releaseStatusTable))
    {
        Dialog dialog;
        DialogField dlgFld;

        dialog = new Dialog(strFmt("@NDX:NXASetCalendarFromDate", _releaseStatusTable.CalendarId));
        dlgFld = dialog.addFieldValue(extendedTypeStr(FromDate), DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        dialog.run();
        if (dialog.closedOk())
        {
            args.parm(date2Str(dlgFld.value(), 123, 2, DateSeparator::Dot, 2, DateSeparator::Dot, 4));
            ret = true;
        }
        else
        {
            ret = false;
        }

        if (ret)
        {
            args.record(this);
            menuFunction = new MenuFunction(menuItemActionStr(AVAUpdateResourceCalendar), MenuItemType::Action);
            menuFunction.run(args);
        }
    }

    return ret;
}
